171	        return this.membershipNumber;
172	    }
173	
174	    public void setMembershipNumber(String membershipNumber) {
175	        this.membershipNumber = membershipNumber;
176	    }
177	
178	    public Boolean getBulkSignupWarning() {
179	        return this.bulkSignupWarning;
180	    }
181	
182	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
183	        this.bulkSignupWarning = bulkSignupWarning;
184	    }
