203	        return this.possibleDuplicateOf;
204	    }
205	
206	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
207	        this.possibleDuplicateOf = possibleDuplicateOf;
208	    }
209	
210	    /**
211	     * The owner's membership points, derived at read time from stored fields. Starts at 0; add 2 when
212	     * an email is present; add 1 when {@link #getNamesakeCount() namesakeCount} is 0; add 2 for a
213	     * household of 3 or more ({@link #getHouseholdSize() householdSize}); add 3 when tenure (days since
214	     * {@link #getRegistrationDate() registrationDate}) exceeds 365. A newly created owner has zero
215	     * tenure, so a new owner can score at most 5 points.
216	     */
217	    @Transient
218	    public Integer getMembershipPoints() {
219	        int points = 0;
220	        boolean hasEmail = this.email != null && !this.email.isBlank();
221	        if (hasEmail) {
222	            points += 2;
223	        }
224	        if (this.namesakeCount != null && this.namesakeCount == 0) {
225	            points += 1;
226	        }
227	        if (this.householdSize != null && this.householdSize >= 3) {
228	            points += 2;
229	        }
230	        if (this.registrationDate != null
231	                && java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
232	            points += 3;
233	        }
234	        return points;
235	    }
236	
237	    /**
238	     * The owner's membership level, a number from 1 to 4 derived at read time by banding
239	     * {@link #getMembershipPoints() membershipPoints}: 1 (0-1 points), 2 (2-3), 3 (4-5), 4 (6 or more).
240	     * Because a new owner scores at most 5 points, only tenure (+3) can reach level 4.
241	     */
242	    @Transient
243	    public Integer getMembershipLevel() {
244	        int points = getMembershipPoints();
245	        if (points <= 1) {
246	            return 1;
247	        }
248	        if (points <= 3) {
249	            return 2;
250	        }
251	        if (points <= 5) {
252	            return 3;
253	        }
254	        return 4;
255	    }
256	
257	    /**
258	     * A single Luhn check digit (0-9) computed at read time over the digits contained in the
259	     * {@link #getCustomerCode() customerCode} (non-digit characters such as the '-' separators are
260	     * ignored). {@code null} when the owner has no customerCode.
261	     */
262	    @Transient
263	    public Integer getCheckDigit() {
264	        if (this.customerCode == null) {
265	            return null;
266	        }
267	        int sum = 0;
268	        boolean dbl = true;
269	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
270	            char c = this.customerCode.charAt(i);
271	            if (c < '0' || c > '9') {
272	                continue;
273	            }
274	            int d = c - '0';
275	            if (dbl) {
276	                d *= 2;
277	                if (d > 9) {
278	                    d -= 9;
279	                }
280	            }
281	            sum += d;
282	            dbl = !dbl;
283	        }
284	        return (10 - (sum % 10)) % 10;
285	    }
286	
287	    /**
288	     * The owner's region, derived at read time. The {@link #getPostcode() postcode} is preferred:
289	     * a 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
290	     * QLD 4000-4099) yields that region, which disambiguates cities that share a name. Only when the
291	     * postcode is absent (or in no known range) does it fall back to the fixed city-to-region table
292	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}). Any unresolved value
293	     * yields {@code 'UNKNOWN'}.
294	     */
295	    @Transient
296	    public String getLocality() {
297	        String byPostcode = regionForPostcode(this.postcode);
298	        if (byPostcode != null) {
299	            return byPostcode;
300	        }
301	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
302	    }
303	
304	    /**
305	     * The owner's IANA timezone, derived at read time from the owner's region
306	     * ({@link #getLocality()}) via the pinned region-to-timezone table (NSW->Australia/Sydney,
307	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane). {@code null} when the region is unknown.
308	     */
309	    @Transient
310	    public String getTimezone() {
311	        return REGION_TIMEZONE.get(getLocality());
312	    }
313	
314	    /** The region whose range contains {@code postcode}, or {@code null} when absent/out of range. */
315	    private static String regionForPostcode(String postcode) {
316	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
317	            return null;
318	        }
319	        int value = Integer.parseInt(postcode);
320	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
321	            int[] range = entry.getValue();
322	            if (value >= range[0] && value <= range[1]) {
323	                return entry.getKey();
324	            }
325	        }
326	        return null;
327	    }
328	
329	    /**
330	     * The stored E.164 {@link #getTelephone() telephone} formatted for humans, derived at read
331	     * time: the country code, a space, then the national digits grouped in threes (e.g.
332	     * {@code '+61412345678'} yields {@code '+61 412 345 678'}). Known country codes ({@code '+61'},
333	     * {@code '+1'}) are split off explicitly; otherwise a two-digit country code is assumed. The
334	     * raw {@link #getTelephone() telephone} itself stays in E.164 form. {@code null} when the owner
335	     * has no telephone or it is not a well-formed E.164 number.
336	     */
337	    @Transient
338	    public String getTelephoneDisplay() {
339	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
340	            return null;
341	        }
342	        String digits = this.telephone.substring(1); // drop the leading '+'
343	        String countryCode = countryCodeOf(digits);
344	        String national = digits.substring(countryCode.length());
345	        StringBuilder display = new StringBuilder("+").append(countryCode);
346	        display.append(' ');
347	        for (int i = 0; i < national.length(); i++) {
348	            if (i > 0 && i % 3 == 0) {
349	                display.append(' ');
350	            }
351	            display.append(national.charAt(i));
352	        }
353	        return display.toString();
354	    }
355	
356	    /**
357	     * The E.164 country code at the start of {@code digits} (the '+'-stripped number). Known codes
358	     * are matched longest-first; any other number falls back to a two-digit country code.
359	     */
360	    private static String countryCodeOf(String digits) {
361	        for (String code : KNOWN_COUNTRY_CODES) {
362	            if (digits.startsWith(code) && digits.length() > code.length()) {
363	                return code;
364	            }
365	        }
366	        return digits.length() > 2 ? digits.substring(0, 2) : digits;
367	    }
368	
369	    /** Recognised E.164 country codes, longest-first, for {@link #getTelephoneDisplay()}. */
370	    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");
371	
372	    /**
373	     * The owner's preferred contact channel, derived at read time: {@code 'EMAIL'} when an
374	     * {@link #getEmail() email} is present, otherwise {@code 'PHONE'}.
375	     */
376	    @Transient
377	    public String getContactPreference() {
378	        boolean hasEmail = this.email != null && !this.email.isBlank();
379	        return hasEmail ? "EMAIL" : "PHONE";
380	    }
381	
382	    /**
383	     * The owner's age band, derived at read time from {@link #getBirthDate() birthDate} measured
384	     * against the {@link #getRegistrationDate() registrationDate}: {@code 'MINOR'} when the owner is
385	     * under 18 at registration, {@code 'ADULT'} from 18 to 64, {@code 'SENIOR'} at 65 or over.
386	     * {@code null} when the owner has no birthDate (or no registrationDate to measure against).
387	     */
388	    @Transient
389	    public String getAgeBand() {
390	        if (this.birthDate == null || this.registrationDate == null) {
391	            return null;
392	        }
393	        int years = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
394	        if (years < 18) {
395	            return "MINOR";
396	        }
397	        if (years < 65) {
398	            return "ADULT";
399	        }
400	        return "SENIOR";
401	    }
402	
403	    /**
404	     * The single derived duplicate-detection key, {@code normalizedTelephone|email|householdId}
405	     * (the normalized telephone, the email or empty when absent, and the householdId or empty when
406	     * the owner has a unique household). All duplicate detection is expressed through this one key:
407	     * a create whose WHOLE identityKey equals an existing owner's is a duplicate. Because the
408	     * telephone is part of the key, two members of the same household with different telephones have
409	     * different identityKeys and are both allowed.
410	     */
411	    @Transient
412	    public String getIdentityKey() {
413	        String tel = this.telephone == null ? "" : this.telephone;
414	        String mail = (this.email == null || this.email.isBlank()) ? "" : this.email;
415	        String household = (this.householdId == null || this.householdId.isBlank()) ? "" : this.householdId;
416	        return tel + "|" + mail + "|" + household;
417	    }
418	
419	    /** City -> canonical region for {@link #getLocality()}. Any other city is 'UNKNOWN'. */
420	    private static final Map<String, String> CITY_REGION =
421	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
422	
423	    /** Region -> IANA timezone for {@link #getTimezone()}. */
424	    private static final Map<String, String> REGION_TIMEZONE =
425	        Map.of("NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
426	
427	    /** Region -> inclusive 4-digit postcode range {low, high}, preferred by {@link #getLocality()}. */
428	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
429	        "NSW", new int[] {2000, 2099},
430	        "VIC", new int[] {3000, 3099},
431	        "QLD", new int[] {4000, 4099});
432	
433	    protected Set<Pet> getPetsInternal() {
434	        if (this.pets == null) {
435	            this.pets = new HashSet<>();
436	        }
437	        return this.pets;
438	    }
439	
440	    protected void setPetsInternal(Set<Pet> pets) {
441	        this.pets = pets;
442	    }
443	
444	    public List<Pet> getPets() {
445	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
446	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
447	        return Collections.unmodifiableList(sortedPets);
448	    }
449	
450	    public void setPets(List<Pet> pets) {
451	        this.pets = new HashSet<>(pets);
452	    }
453	
454	    public void addPet(Pet pet) {
455	        getPetsInternal().add(pet);
456	        pet.setOwner(this);
457	    }
458	
459	    /**
460	     * Return the Pet with the given name, or null if none found for this Owner.
461	     *
462	     * @param name to test
463	     * @return true if pet name is already in use
464	     */
465	    public Pet getPet(String name) {
466	        return getPet(name, false);
467	    }
468	
469	    /**
470	     * Return the Pet with the given name, or null if none found for this Owner.
471	     *
472	     * @param name to test
473	     * @return true if pet name is already in use
474	     */
475	    public Pet getPet(String name, boolean ignoreNew) {
476	        name = name.toLowerCase();
477	        for (Pet pet : getPetsInternal()) {
478	            if (!ignoreNew || !pet.isNew()) {
479	                String compName = pet.getName();
480	                compName = compName.toLowerCase();
481	                if (compName.equals(name)) {
482	                    return pet;
483	                }
484	            }
485	        }
486	        return null;
487	    }
488	
489	    public Pet getPet(Integer petId) {
490	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
491	    }
492	
493	    @Override
494	    public String toString() {
495	        return new ToStringCreator(this)
496	
497	            .append("id", this.getId())
498	            .append("new", this.isNew())
499	            .append("lastName", this.getLastName())
500	            .append("firstName", this.getFirstName())
501	            .append("address", this.address)
502	            .append("city", this.city)
503	            .append("telephone", this.telephone)
504	            .toString();
505	    }
506	}
